<script setup lang="ts">
// 富化产出详情独立页：/manage/problem-enrichment/detail/:problemKey。
// 相比抽屉，独立页面有完整宽度与独立 URL（可刷新/收藏/分享），
// 从题目列表「查看产出」、审核卡片「全部产出」、总览活动与失败面板、题目详情页统一跳转到这里。
import { ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, type GlobalProperties } from "@/util/tips";
import { PostEnrichRequeue } from "@/apis/problem-enrichment";
import EnrichProblemDetailBody from "./EnrichProblemDetailBody.vue";
import EnrichCuratorDrawer from "./EnrichCuratorDrawer.vue";

const route = useRoute();
const router = useRouter();
const globalProperties = useCurrentInstance().globalProperties as GlobalProperties;

// path 路由：题目 key（可读 URL）；后端对数字 key 有 id 兜底
const problemKey = String(route.params.problemKey || "");
const detailTitle = ref("");

// 重判/人工定稿后递增，Body 自动刷新
const dataVersion = ref(0);

const backToConsole = () => {
  router.push({ name: "manage-problem-enrichment" });
};

// 来源是站内（从题目页/后台跳入）时返回来源，否则回富化后台
const goBack = () => {
  if (window.history.length > 1) {
    router.back();
  } else {
    backToConsole();
  }
};

const requeue = async (id: number) => {
  try {
    const res = await PostEnrichRequeue(id);
    if (res.code === 0) {
      dataVersion.value++;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "重判失败");
  }
};

// 人工标注 / 校正抽屉
const curatorVisible = ref(false);
const curatorProblemId = ref(0);
const curatorTaskType = ref("summary");
const curatorReviewMode = ref(false);

const openCurator = (id: number, taskType: string) => {
  curatorProblemId.value = id;
  curatorTaskType.value = taskType;
  curatorReviewMode.value = false;
  curatorVisible.value = true;
};

const onCuratorSaved = () => {
  curatorVisible.value = false;
  dataVersion.value++;
};

const onCuratorRejected = () => {
  curatorVisible.value = false;
  dataVersion.value++;
};

// Body 加载完成后更新面包屑标题
const onLoaded = (p: { key?: string; title?: string } | undefined) => {
  detailTitle.value = p ? `#${p.key} ${p.title}` : "";
};
</script>

<template>
  <div class="enrich-detail-page">
    <t-card>
      <!-- 面包屑导航：题目富化 / 产出详情，返回按钮回到来源 -->
      <div class="page-head">
        <t-button variant="text" theme="primary" @click="goBack">
          <template #icon><t-icon name="chevron-left" /></template>
          返回
        </t-button>
        <t-breadcrumb>
          <t-breadcrumb-item @click="backToConsole">AI 审阅</t-breadcrumb-item>
          <t-breadcrumb-item>{{ detailTitle || "产出详情" }}</t-breadcrumb-item>
        </t-breadcrumb>
      </div>

      <EnrichProblemDetailBody
        v-if="problemKey"
        :problem-id="0"
        :problem-key="problemKey"
        :data-version="dataVersion"
        :active="true"
        @open-curator="openCurator"
        @requeue="requeue"
        @loaded="onLoaded"
      />
      <div v-else class="detail-empty">
        缺少题目编号（请从富化后台的「查看产出」进入）
      </div>
    </t-card>

    <!-- 人工标注 / 校正抽屉 -->
    <EnrichCuratorDrawer
      :visible="curatorVisible"
      :problem-id="curatorProblemId"
      :initial-task-type="curatorTaskType"
      :review-mode="curatorReviewMode"
      @saved="onCuratorSaved"
      @rejected="onCuratorRejected"
      @update:visible="(v: boolean) => (curatorVisible = v)"
    />
  </div>
</template>

<style scoped>
.enrich-detail-page {
  padding: 10px;
  max-width: 1100px;
}

.page-head {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 8px;
}

.detail-empty {
  color: var(--td-text-color-placeholder);
  text-align: center;
  padding: 24px 0;
}
</style>
